module adder_pipe_64bit #(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
) (
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output reg [DATA_WIDTH:0] result,
    output reg o_en
);

    parameter PIPE_STAGES = 3;

    reg [63:0] pipe_reg_a [PIPE_STAGES];
    reg [63:0] pipe_reg_b [PIPE_STAGES];
    reg [63:0] pipe_carry [PIPE_STAGES];
    reg [64:0] pipe_result [PIPE_STAGES];
    reg o_en_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pipe_reg_a[0] <= 64'd0;
            pipe_reg_b[0] <= 64'd0;
            pipe_carry[0] <= 1'b0;
            pipe_result[0] <= 65'd0;
        end else if (i_en) begin
            pipe_reg_a[0] <= adda;
            pipe_reg_b[0] <= addb;
            pipe_carry[0] <= 1'b0;
            pipe_result[0] <= adda + addb;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pipe_reg_a[1] <= 64'd0;
            pipe_reg_b[1] <= 64'd0;
            pipe_carry[1] <= 1'b0;
            pipe_result[1] <= 65'd0;
        end else begin
            pipe_reg_a[1] <= pipe_reg_a[0];
            pipe_reg_b[1] <= pipe_reg_b[0];
            pipe_carry[1] <= pipe_carry[0];
            pipe_result[1] <= pipe_result[0] + {1'b0, pipe_carry[0]};
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pipe_reg_a[2] <= 64'd0;
            pipe_reg_b[2] <= 64'd0;
            pipe_carry[2] <= 1'b0;
            pipe_result[2] <= 65'd0;
        end else begin
            pipe_reg_a[2] <= pipe_reg_a[1];
            pipe_reg_b[2] <= pipe_reg_b[1];
            pipe_carry[2] <= pipe_carry[1];
            pipe_result[2] <= pipe_result[1] + {1'b0, pipe_carry[1]};
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            o_en_reg <= 1'b0;
        end else begin
            o_en_reg <= pipe_carry[2];
        end
    end

    assign result = pipe_result[2];
    assign o_en = o_en_reg;

endmodule
